tool_calls:
mkdir -p /home/eval/recon/out && cat > /home/eval/recon/recon.awk <<'EOF'
# Reconcile ledger.csv (RFC 4180 CSV) against bank.tsv (TSV).
# All money handled as integer cents.

# ---- RFC 4180 CSV line parser: fills out[1..nf], returns nf ----
function parse_csv(line, out,   i, n, c, cur, nf, inq) {
    n = length(line); cur = ""; nf = 0; inq = 0; i = 1
    while (i <= n) {
        c = substr(line, i, 1)
        if (inq) {
            if (c == "\"") {
                if (substr(line, i + 1, 1) == "\"") { cur = cur "\""; i += 2; continue }
                inq = 0; i++; continue            # closing quote
            }
            cur = cur c; i++; continue
        } else {
            if (c == "\"")      { inq = 1; i++; continue }
            else if (c == ",")  { out[++nf] = cur; cur = ""; i++; continue }
            else                { cur = cur c; i++; continue }
        }
    }
    out[++nf] = cur
    return nf
}

# ---- decimal string -> integer cents (exact; truncates a 3rd decimal) ----
function to_cents(s,   neg, p, ip, fp, v) {
    gsub(/[[:space:]]/, "", s)
    gsub(/,/, "", s)                       # thousands separators
    neg = 0
    if (substr(s, 1, 1) == "-")      { neg = 1; s = substr(s, 2) }
    else if (substr(s, 1, 1) == "+") { s = substr(s, 2) }
    if (s !~ /\./) { ip = s; fp = "" }
    else           { p = index(s, "."); ip = substr(s, 1, p - 1); fp = substr(s, p + 1) }
    if (ip == "") ip = "0"
    fp = substr(fp "00", 1, 2)             # pad/truncate to exactly 2 digits
    v = (ip + 0) * 100 + (fp + 0)
    return neg ? -v : v
}

function fmt(c) { return sprintf("%d.%02d", int(c / 100), c % 100) }

BEGIN { FS = "\t" }

FNR == 1 { next }                          # header line of either file
{ sub(/\r$/, "", $0) }

FILENAME == LEDGER {
    parse_csv($0, f)
    id = f[1]; dt = f[2]; cents = to_cents(f[4])
    Ldate[id] = dt; Lcents[id] = cents
    all[id] = 1
    ledger_rows++; ltotal += cents
    next
}

FILENAME == BANK {
    ref = $1
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", ref)   # trim
    ref = toupper(ref)                             # normalise case
    split($2, d, "/")
    dt = d[3] "-" d[2] "-" d[1]                    # DD/MM/YYYY -> YYYY-MM-DD
    cents = to_cents($4)
    key = ref SUBSEP dt SUBSEP cents
    if (key in seen) { dups++; next }              # duplicate bank row: drop
    seen[key] = 1
    Bdate[ref] = dt; Bcents[ref] = cents
    all[ref] = 1
    bank_rows++; btotal += cents
    next
}

END {
    PROCINFO["sorted_in"] = "@ind_str_asc"
    n_match = 0; n_am = 0; n_dm = 0; n_mb = 0; n_ml = 0
    for (id in all) {
        inL = (id in Lcents); inB = (id in Bcents)
        if (inL && inB) {
            if (Lcents[id] == Bcents[id] && Ldate[id] == Bdate[id]) n_match++
            if (Lcents[id] != Bcents[id]) am[++n_am] = id
            if (Ldate[id]  != Bdate[id])  dm[++n_dm] = id
        } else if (inL) mb[++n_mb] = id
        else            ml[++n_ml] = id
    }

    print "ledger_rows: " ledger_rows
    print "bank_rows: " bank_rows
    print "duplicate_bank_rows: " dups + 0
    print "ledger_total: " fmt(ltotal)
    print "bank_total: " fmt(btotal)
    print "matched: " n_match

    print "amount_mismatch: " n_am
    for (i = 1; i <= n_am; i++) {
        id = am[i]
        printf "  %s ledger=%s bank=%s\n", id, fmt(Lcents[id]), fmt(Bcents[id])
    }
    print "date_mismatch: " n_dm
    for (i = 1; i <= n_dm; i++) {
        id = dm[i]
        printf "  %s ledger=%s bank=%s\n", id, Ldate[id], Bdate[id]
    }
    print "missing_in_bank: " n_mb
    for (i = 1; i <= n_mb; i++) print "  " mb[i]
    print "missing_in_ledger: " n_ml
    for (i = 1; i <= n_ml; i++) print "  " ml[i]
}
EOF
echo written

